.dwv-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dwv-root,.dwv-root *,.dwv-root *::before,.dwv-root *::after{box-sizing:border-box}
.dwv-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dwv-root img{display:block;border:0;max-width:none}
.dwv-root > [data-node-id]{will-change:transform}
.dwv-root [hidden]{display:none!important}
.dwv-root [data-sh-theme="dark"]{display:none!important}
.dwv-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.dwv-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.dwv-root .n1_9882{background-color:var(--wa-bg, #e3eafb);align-content:stretch;display:flex;gap:6px;align-items:center;justify-content:center;padding-left:14px;padding-right:14px;padding-top:6px;padding-bottom:6px;position:relative;border-radius:6px;flex-shrink:0}
.dwv-root .n1_9882::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-point, #ced6e9);border-radius:6px;pointer-events:none}
.dwv-root .n1_9883{position:relative;flex-shrink:0;width:13px;height:13px}
.dwv-root .x306{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.dwv-root .n1_9884{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:normal;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #414651);font-size:12px;white-space:nowrap}
