.dwv-root[data-theme="dark"] [data-name="Header"] > [data-name="Background"]{background:var(--wa-bg, #131519)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.06)!important}
.dwv-root[data-theme="dark"] [data-name="Input"],.dwv-root[data-theme="dark"] [data-name="Select"],.dwv-root[data-theme="dark"] [data-name^="Field/ID"],.dwv-root[data-theme="dark"] [data-name^="Field/Password"]{background-color:var(--wa-bg, #111316)}
